def build_messages(system, user):
    return [
        {"role": "system", "content": system},
        {"role": "user", "content": user},
    ]

def tokens(m):
    return len(m["content"]) // 4 + 1

def trim(messages, max_tokens):
    system, rest = messages[0], messages[1:]
    budget = max_tokens - tokens(system)
    kept = []
    for m in reversed(rest):
        if tokens(m) <= budget:
            kept.append(m)
            budget -= tokens(m)
        else:
            break
    return [system] + list(reversed(kept))

import json

def parse_label(raw):
    try:
        data = json.loads(raw)
        label = data["label"]
    except (ValueError, KeyError, TypeError):
        return "unknown"
    return label if label in ("phish", "ok") else "unknown"

